input.command:
source ~/.config/exa/.env && curl -s -X POST "https://api.exa.ai/search" \
  -H "Content-Type: application/json" \
  -H "x-api-key: $EXA_API_KEY" \
  -d '{
    "query": "beautiful interactive visualization of a personal skills and tools graph on a developer portfolio website, alternatives to a mind map or node-link graph",
    "type": "auto",
    "contents": { "highlights": true }
  }' > /tmp/exa-search-1.json; echo "EXIT:$?"; wc -c /tmp/exa-search-1.json

