---
// Force-directed layout adapted from LemonAdorable/astro-theme-iris
// (src/components/graph/KnowledgeGraph.astro + knowledge-graph.ts, Apache-2.0).
// https://github.com/LemonAdorable/astro-theme-iris
import type { SkillEntry } from "@data/skills";

interface Props {
  entries: SkillEntry[];
}

const { entries } = Astro.props;
---

<div class="skills-graph">
  <div class="graph-canvas" data-graph-canvas>
    <p data-graph-status>Loading graph...</p>
  </div>
  <aside class="graph-details" data-graph-details>
    <span>Node</span>
    <h2>Click a node</h2>
    <p>See its tags, agent, and domain.</p>
  </aside>
</div>

<script type="application/json" data-graph-entries set:html={JSON.stringify(entries)} />

<script>
  import * as d3 from "d3";
  import type { SkillEntry } from "@data/skills";

  interface GraphNode extends d3.SimulationNodeDatum {
    id: string;
    entry: SkillEntry;
  }

  interface GraphEdge extends d3.SimulationLinkDatum<GraphNode> {
    source: string | GraphNode;
    target: string | GraphNode;
    tag: string;
  }

  const scriptEl = document.querySelector<HTMLScriptElement>("[data-graph-entries]");
  const entries: SkillEntry[] = scriptEl ? JSON.parse(scriptEl.textContent || "[]") : [];

  const colors: Record<SkillEntry["type"], string> = {
    skill: "var(--color-accent)",
    tool: "var(--color-focus)",
  };

  function buildGraph(entries: SkillEntry[]) {
    const nodes: GraphNode[] = entries.map((entry) => ({ id: entry.name, entry }));
    const edges: GraphEdge[] = [];
    for (let i = 0; i < entries.length; i += 1) {
      for (let j = i + 1; j < entries.length; j += 1) {
        const shared = entries[i].tags.find((tag) => entries[j].tags.includes(tag));
        if (shared) edges.push({ source: entries[i].name, target: entries[j].name, tag: shared });
      }
    }
    return { nodes, edges };
  }

  function render() {
    const canvas = document.querySelector<HTMLElement>("[data-graph-canvas]");
    const details = document.querySelector<HTMLElement>("[data-graph-details]");
    if (!canvas || !details) return;

    const { nodes, edges } = buildGraph(entries);
    const width = canvas.clientWidth || 760;
    const height = canvas.clientHeight || 520;
    canvas.innerHTML = "";

    const svg = d3
      .select(canvas)
      .append("svg")
      .attr("viewBox", `0 0 ${width} ${height}`)
      .attr("role", "img")
      .attr("aria-label", "Skills and tools graph");

    const viewport = svg.append("g");
    svg.call(
      d3
        .zoom<SVGSVGElement, unknown>()
        .scaleExtent([0.4, 3])
        .on("zoom", (event) => viewport.attr("transform", event.transform))
    );

    const link = viewport
      .append("g")
      .selectAll("line")
      .data(edges)
      .join("line")
      .attr("stroke", "var(--color-rule)")
      .attr("stroke-width", 1.2);

    const node = viewport.append("g").selectAll("g").data(nodes).join("g").style("cursor", "pointer");

    node
      .append("circle")
      .attr("r", 9)
      .attr("fill", (d) => `${colors[d.entry.type]}33`)
      .attr("stroke", (d) => colors[d.entry.type])
      .attr("stroke-width", 1.5);

    node
      .append("text")
      .attr("x", 13)
      .attr("y", 4)
      .attr("fill", "var(--color-ink)")
      .attr("font-size", 11)
      .text((d) => d.entry.name);

    node.on("click", (_event, d) => {
      details.innerHTML = `
        <span>Node</span>
        <h2>${d.entry.name}</h2>
        <p>${d.entry.type} · ${d.entry.domain} · ${d.entry.agent}</p>
        <p>${d.entry.tags.map((t) => `#${t}`).join(" ")}</p>
      `;
    });

    const simulation = d3
      .forceSimulation<GraphNode>(nodes)
      .force(
        "link",
        d3
          .forceLink<GraphNode, GraphEdge>(edges)
          .id((d) => d.id)
          .distance(70)
      )
      .force("charge", d3.forceManyBody().strength(-140))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collide", d3.forceCollide(28))
      .on("tick", () => {
        link
          .attr("x1", (d) => (d.source as GraphNode).x ?? 0)
          .attr("y1", (d) => (d.source as GraphNode).y ?? 0)
          .attr("x2", (d) => (d.target as GraphNode).x ?? 0)
          .attr("y2", (d) => (d.target as GraphNode).y ?? 0);
        node.attr("transform", (d) => `translate(${d.x ?? 0},${d.y ?? 0})`);
      });

    node.call(
      d3
        .drag<SVGGElement, GraphNode>()
        .on("start", (event, d) => {
          if (!event.active) simulation.alphaTarget(0.2).restart();
          d.fx = d.x;
          d.fy = d.y;
        })
        .on("drag", (event, d) => {
          d.fx = event.x;
          d.fy = event.y;
        })
        .on("end", (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null;
          d.fy = null;
        })
    );
  }

  render();
</script>

<style>
  .skills-graph {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(14rem, 18rem);
    gap: 1rem;
    height: 32rem;
  }

  .graph-canvas {
    position: relative;
    min-width: 0;
    border: 1px solid var(--color-rule);
    border-radius: 0.75rem;
    overflow: hidden;
  }

  .graph-canvas p {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    margin: 0;
    color: var(--color-muted);
    font-size: 0.85rem;
  }

  .graph-canvas svg {
    display: block;
    width: 100%;
    height: 100%;
  }

  .graph-details {
    padding: 1rem;
    border: 1px solid var(--color-rule);
    border-radius: 0.75rem;
  }

  .graph-details span {
    color: var(--color-accent);
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .graph-details h2 {
    margin: 0.4rem 0 0.3rem;
    font-size: 1rem;
    color: var(--color-ink);
  }

  .graph-details p {
    margin: 0.2rem 0;
    color: var(--color-muted);
    font-size: 0.8rem;
  }

  @media (max-width: 639px) {
    .skills-graph {
      grid-template-columns: 1fr;
      height: auto;
    }

    .graph-canvas {
      height: 24rem;
    }
  }
</style>

