    height: 100%;
  }

  .graph-details {
    padding: 1rem;
    border: 1px solid var(--color-rule);
    border-radius: 0.75rem;
  }

  .graph-details span {
    color: var(--color-accent);
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .graph-details h2 {
    margin: 0.4rem 0 0.3rem;
    font-size: 1rem;
    color: var(--color-ink);
  }

  .graph-details p {
    margin: 0.2rem 0;
    color: var(--color-muted);
    font-size: 0.8rem;
  }

  @media (max-width: 639px) {
    .skills-graph {
      grid-template-columns: 1fr;
      height: auto;
    }

    .graph-canvas {
      height: 24rem;
    }
