---
// Force-directed layout adapted from LemonAdorable/astro-theme-iris
// (src/components/graph/KnowledgeGraph.astro + knowledge-graph.ts, Apache-2.0).
// https://github.com/LemonAdorable/astro-theme-iris
import type { SkillEntry } from "@data/skills";

interface Props {
  entries: SkillEntry[];
}

const { entries } = Astro.props;
---

<div class="graph-toolbar">
  <label class="graph-search">
    <span>Find a node</span>
    <input type="search" placeholder="Search by name..." data-graph-search autocomplete="off" />
    <div data-graph-suggestions hidden></div>
  </label>
</div>

<div class="skills-graph">
  <div class="graph-canvas" data-graph-canvas>
    <p data-graph-status>Loading graph...</p>
  </div>
  <aside class="graph-details" data-graph-details>
    <span>Node</span>
    <h2>Click a node</h2>
    <p>See its tags, agent, and domain.</p>
  </aside>
</div>

<script type="application/json" data-graph-entries set:html={JSON.stringify(entries)} />

<script>
  import * as d3 from "d3";
  import type { SkillEntry } from "@data/skills";

  interface GraphNode extends d3.SimulationNodeDatum {
    id: string;
    entry: SkillEntry;
  }

  interface GraphEdge extends d3.SimulationLinkDatum<GraphNode> {
    source: string | GraphNode;
    target: string | GraphNode;
    tag: string;
  }

  const scriptEl = document.querySelector<HTMLScriptElement>("[data-graph-entries]");
  const entries: SkillEntry[] = scriptEl ? JSON.parse(scriptEl.textContent || "[]") : [];

  const colors: Record<SkillEntry["type"], string> = {
    skill: "var(--color-accent)",
    tool: "var(--color-focus)",
  };

  function buildGraph(entries: SkillEntry[]) {
    const nodes: GraphNode[] = entries.map((entry) => ({ id: entry.name, entry }));
    const edges: GraphEdge[] = [];
    for (let i = 0; i < entries.length; i += 1) {
      for (let j = i + 1; j < entries.length; j += 1) {
        const shared = entries[i].tags.find((tag) => entries[j].tags.includes(tag));
        if (shared) edges.push({ source: entries[i].name, target: entries[j].name, tag: shared });
      }
    }
    return { nodes, edges };
  }

  function showDetails(details: HTMLElement, entry: SkillEntry) {
    details.innerHTML = `
      <span>Node</span>
      <h2>${entry.name}</h2>
      <p>${entry.type} · ${entry.domain} · ${entry.agent}</p>
      <p>${entry.tags.map((t) => `#${t}`).join(" ")}</p>
    `;
  }

  let zoomToNode: ((id: string) => void) | null = null;

  function render() {
    const canvas = document.querySelector<HTMLElement>("[data-graph-canvas]");
    const details = document.querySelector<HTMLElement>("[data-graph-details]");
    if (!canvas || !details) return;

    const { nodes, edges } = buildGraph(entries);
    const width = canvas.clientWidth || 760;
    const height = canvas.clientHeight || 520;
    canvas.innerHTML = "";

    const svg = d3
      .select(canvas)
      .append("svg")
      .attr("viewBox", `0 0 ${width} ${height}`)
      .attr("role", "img")
      .attr("aria-label", "Skills and tools graph");

    const viewport = svg.append("g");
    const zoomBehavior = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.4, 3])
      .on("zoom", (event) => viewport.attr("transform", event.transform));
    svg.call(zoomBehavior);

    const link = viewport
      .append("g")
      .selectAll("line")
      .data(edges)
      .join("line")
      .attr("stroke", "var(--color-rule)")
      .attr("stroke-width", 1.2);

    const node = viewport.append("g").selectAll("g").data(nodes).join("g").style("cursor", "pointer");

    node
      .append("circle")
      .attr("r", 9)
      .attr("fill", (d) => `${colors[d.entry.type]}33`)
      .attr("stroke", (d) => colors[d.entry.type])
      .attr("stroke-width", 1.5);

    node
      .append("text")
      .attr("x", 13)
      .attr("y", 4)
      .attr("fill", "var(--color-ink)")
      .attr("font-size", 11)
      .text((d) => d.entry.name);

    node.on("click", (_event, d) => showDetails(details, d.entry));

    const simulation = d3
      .forceSimulation<GraphNode>(nodes)
      .force(
        "link",
        d3
          .forceLink<GraphNode, GraphEdge>(edges)
          .id((d) => d.id)
          .distance(70)
      )
      .force("charge", d3.forceManyBody().strength(-140))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collide", d3.forceCollide(28))
      .on("tick", () => {
        link
          .attr("x1", (d) => (d.source as GraphNode).x ?? 0)
          .attr("y1", (d) => (d.source as GraphNode).y ?? 0)
          .attr("x2", (d) => (d.target as GraphNode).x ?? 0)
          .attr("y2", (d) => (d.target as GraphNode).y ?? 0);
        node.attr("transform", (d) => `translate(${d.x ?? 0},${d.y ?? 0})`);
      });

    node.call(
      d3
        .drag<SVGGElement, GraphNode>()
        .on("start", (event, d) => {
          if (!event.active) simulation.alphaTarget(0.2).restart();
          d.fx = d.x;
          d.fy = d.y;
        })
        .on("drag", (event, d) => {
          d.fx = event.x;
          d.fy = event.y;
        })
        .on("end", (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null;
          d.fy = null;
        })
    );

    zoomToNode = (id: string) => {
      const target = nodes.find((n) => n.id === id);
      if (!target) return;
      showDetails(details, target.entry);
      node
        .select("circle")
        .attr("stroke-width", (d) => (d.id === id ? 3 : 1.5));
      svg
        .transition()
        .duration(450)
        .call(
          zoomBehavior.transform,
          d3.zoomIdentity
            .translate(width / 2, height / 2)
            .scale(1.8)
            .translate(-(target.x ?? width / 2), -(target.y ?? height / 2))
        );
    };
  }

  render();

  const search = document.querySelector<HTMLInputElement>("[data-graph-search]");
  const suggestions = document.querySelector<HTMLElement>("[data-graph-suggestions]");
  if (search && suggestions) {
    search.addEventListener("input", () => {
      const query = search.value.trim().toLowerCase();
      suggestions.replaceChildren();
      if (!query) {
        suggestions.hidden = true;
        return;
      }
      const matches = entries.filter((e) => e.name.toLowerCase().includes(query)).slice(0, 8);
      matches.forEach((entry) => {
        const button = document.createElement("button");
        button.type = "button";
        button.dataset.suggestion = "";
        button.textContent = entry.name;
        button.addEventListener("click", () => {
          search.value = entry.name;
          suggestions.hidden = true;
          zoomToNode?.(entry.name);
        });
        suggestions.append(button);
      });
      suggestions.hidden = matches.length === 0;
    });

    search.addEventListener("keydown", (event) => {
      if (event.key !== "Enter") return;
      const query = search.value.trim().toLowerCase();
      const match = entries.find((e) => e.name.toLowerCase().includes(query));
      if (match) {
        suggestions.hidden = true;
        zoomToNode?.(match.name);
      }
    });
  }
</script>

<style>
  .graph-toolbar {
    margin-bottom: 0.75rem;
  }

  .graph-search {
    position: relative;
    display: block;
    max-width: 22rem;
  }

  .graph-search span {
    display: block;
    margin-bottom: 0.3rem;
    color: var(--color-muted);
    font-size: 0.68rem;
    font-weight: 650;
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }

  .graph-search input {
    width: 100%;
    padding: 0.5rem 0.65rem;
    border: 1px solid var(--color-rule);
    border-radius: 0.6rem;
    color: var(--color-ink);
    background: transparent;
    font: inherit;
    font-size: 0.85rem;
  }

  .graph-search div {
    position: absolute;
    top: 100%;
    z-index: 10;
    width: 100%;
    max-height: 14rem;
    overflow: auto;
    margin-top: 0.3rem;
    padding: 0.3rem;
    border: 1px solid var(--color-rule);
    border-radius: 0.6rem;
    background: var(--color-bg, canvas);
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.12);
  }

  .graph-search button {
    display: block;
    width: 100%;
    padding: 0.4rem 0.5rem;
    border: 0;
    border-radius: 0.4rem;
    color: var(--color-ink);
    background: none;
    cursor: pointer;
    text-align: left;
    font-size: 0.8rem;
  }

  .graph-search button:hover {
    background: var(--color-rule);
  }

  .skills-graph {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(14rem, 18rem);
    gap: 1rem;
    height: 44rem;
  }

  .graph-canvas {
    position: relative;
    min-width: 0;
    border: 1px solid var(--color-rule);
    border-radius: 0.75rem;
    overflow: hidden;
  }

  .graph-canvas p {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    margin: 0;
    color: var(--color-muted);
    font-size: 0.85rem;
  }

  .graph-canvas svg {
    display: block;
    width: 100%;
    height: 100%;
  }

  .graph-details {
    padding: 1rem;
    border: 1px solid var(--color-rule);
    border-radius: 0.75rem;
  }

  .graph-details span {
    color: var(--color-accent);
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .graph-details h2 {
    margin: 0.4rem 0 0.3rem;
    font-size: 1rem;
    color: var(--color-ink);
  }

  .graph-details p {
    margin: 0.2rem 0;
    color: var(--color-muted);
    font-size: 0.8rem;
  }

  @media (max-width: 639px) {
    .skills-graph {
      grid-template-columns: 1fr;
      height: auto;
    }

    .graph-canvas {
      height: 30rem;
    }
  }
</style>

