48	<script>
49	  import * as d3 from "d3";
50	  import type { SkillEntry } from "@data/skills";
51	
52	  interface TreeDatum {
53	    name: string;
54	    entry?: SkillEntry; // present on leaves only
55	    children?: TreeDatum[];
56	    _children?: TreeDatum[]; // collapsed children, d3 collapsible-tree convention
57	  }
58	
59	  type HNode = d3.HierarchyPointNode<TreeDatum>;
60	
61	  // Add an entry here to offer another way to branch the tree.
62	  const GROUPINGS: { key: string; label: string; get: (e: SkillEntry) => string }[] = [
63	    { key: "domain", label: "Domain", get: (e) => e.domain },
64	    { key: "agent", label: "Agent", get: (e) => e.agent },
65	    { key: "type", label: "Type", get: (e) => e.type },
66	  ];
67	
68	  const PALETTE = [
69	    "#8b5cf6",
70	    "#0ea5e9",
71	    "#10b981",
72	    "#f59e0b",
73	    "#ef4444",
74	    "#ec4899",
75	    "#14b8a6",
76	    "#6366f1",
77	  ];
78	
79	  const scriptEl = document.querySelector<HTMLScriptElement>("[data-graph-entries]");
80	  const entries: SkillEntry[] = scriptEl ? JSON.parse(scriptEl.textContent || "[]") : [];
81	
82	  let activeGrouping = GROUPINGS[0];
83	  let root: d3.HierarchyNode<TreeDatum>;
84	  let selectedLeafId: string | null = null;
85	  let color: d3.ScaleOrdinal<string, string>;
86	
87	  function buildTree(): TreeDatum {
88	    const groups = new Map<string, TreeDatum[]>();
89	    entries.forEach((entry) => {
90	      const key = activeGrouping.get(entry);
91	      if (!groups.has(key)) groups.set(key, []);
92	      groups.get(key)!.push({ name: entry.name, entry });
93	    });
94	    return {
95	      name: "All",
96	      children: Array.from(groups.entries()).map(([name, children]) => ({ name, children })),
