98	  }
99	
100	  // Collapse every branch node so the initial view is scannable.
101	  function collapseAll(node: d3.HierarchyNode<TreeDatum>) {
102	    if (node.children) {
103	      node.data._children = node.children.map((c) => c.data);
104	      node.children = undefined;
105	    }
106	  }
107	
108	  function expandAll(node: d3.HierarchyNode<TreeDatum>) {
109	    if (node.data._children) {
110	      node.data.children = node.data._children;
111	      node.data._children = undefined;
112	    }
113	  }
114	
115	  function showDetails(details: HTMLElement, entry: SkillEntry) {
116	    const legend = details.querySelector("[data-graph-legend]")?.outerHTML ?? "";
117	    details.innerHTML = `
118	      <span>Node</span>
119	      <h2>${entry.name}</h2>
120	      <p>${entry.type} · ${entry.domain} · ${entry.agent}</p>
121	      <p>${entry.tags.map((t) => `#${t}`).join(" ")}</p>
122	      ${legend}
123	    `;
124	  }
125	
126	  let zoomToNode: ((id: string) => void) | null = null;
127	  let rebuildAndRender: (() => void) | null = null;
128	
129	  function render() {
130	    const canvas = document.querySelector<HTMLElement>("[data-graph-canvas]");
131	    const details = document.querySelector<HTMLElement>("[data-graph-details]");
132	    const legendEl = document.querySelector<HTMLElement>("[data-graph-legend]");
133	    if (!canvas || !details) return;
134	
135	    const width = canvas.clientWidth || 900;
136	    const height = canvas.clientHeight || 640;
137	    canvas.innerHTML = "";
138	
139	    const groupValues = Array.from(new Set(entries.map((e) => activeGrouping.get(e))));
140	    color = d3.scaleOrdinal<string, string>().domain(groupValues).range(PALETTE);
141	
142	    if (legendEl) {
143	      legendEl.innerHTML = groupValues
