145	        .join("");
146	    }
147	
148	    const margin = { top: 20, right: 180, bottom: 20, left: 90 };
149	    const treeLayout = d3.tree<TreeDatum>().size([height - margin.top - margin.bottom, width - margin.left - margin.right]);
150	
151	    const svg = d3
152	      .select(canvas)
153	      .append("svg")
154	      .attr("viewBox", `0 0 ${width} ${height}`)
155	      .attr("role", "img")
156	      .attr("aria-label", "Skills and tools tree");
157	
158	    const viewport = svg.append("g").attr("transform", `translate(${margin.left},${margin.top})`);
