219	        .attr("font-size", 9)
220	        .attr("fill", "var(--color-bg, white)")
221	        .text("+");
222	
223	      node
224	        .append("text")
225	        .attr("x", (d) => (d.children || d.data._children ? -12 : 11))
226	        .attr("y", 3)
227	        .attr("text-anchor", (d) => (d.children || d.data._children ? "end" : "start"))
228	        .attr("fill", "var(--color-ink)")
229	        .attr("font-weight", (d) => (d.data.entry ? 400 : 650))
230	        .attr("font-size", (d) => (d.data.entry ? 10 : 11))
231	        .text((d) => d.data.name);
232	
233	      node.on("click", (_event, d) => {
234	        if (!d.data.entry) {
235	          // Branch node: toggle expand/collapse.
236	          if (d.data.children) {
237	            d.data._children = d.data.children;
238	            d.data.children = undefined;
239	          } else if (d.data._children) {
240	            d.data.children = d.data._children;
241	            d.data._children = undefined;
242	          }
243	          selectedLeafId = null;
244	          crossLinkLayer.selectAll("*").remove();
245	          draw();
246	          return;
247	        }
248	        // Leaf node: select it, show detail, draw cross-links to visible siblings.
249	        selectedLeafId = d.data.entry.name;
250	        showDetails(details, d.data.entry);
251	        drawCrossLinks(d, nodes);
252	        draw();
253	      });
254	
255	      zoomToNode = (id: string) => {
256	        // Expand every ancestor branch so the target leaf is visible.
257	        let found: d3.HierarchyNode<TreeDatum> | null = null;
258	        root.each((n) => {
