272	          .descendants()
273	          .find((n) => (n as HNode).data.entry?.name === id) as HNode | undefined;
274	        if (!target) return;
275	        selectedLeafId = id;
276	        showDetails(details, target.data.entry!);
277	        drawCrossLinks(target, treeLayout(root as d3.HierarchyNode<TreeDatum>).descendants() as HNode[]);
278	        draw();
