280	          .transition()
281	          .duration(450)
282	          .call(
283	            zoomBehavior.transform,
284	            d3.zoomIdentity
285	              .translate(width / 2, height / 2)
286	              .scale(1.6)
287	              .translate(-(target.y + margin.left), -(target.x + margin.top))
288	          );
289	      };
290	    }
291	
292	    function drawCrossLinks(source: HNode, allNodes: HNode[]) {
293	      crossLinkLayer.selectAll("*").remove();
294	      if (!source.data.entry) return;
295	      const sourceTags = new Set(source.data.entry.tags);
