307	        .attr("opacity", 0.75)
308	        .attr("d", (d) => {
309	          const dx = d.y - source.y;
310	          const dy = d.x - source.x;
311	          const dr = Math.sqrt(dx * dx + dy * dy) * 1.4;
312	          return `M${source.y},${source.x} A${dr},${dr} 0 0,1 ${d.y},${d.x}`;
313	        });
314	    }
315	
316	    draw();
317	
318	    rebuildAndRender = () => {
319	      root = d3.hierarchy(buildTree());
320	      root.children?.forEach((child) => collapseAll(child));
321	      selectedLeafId = null;
322	      render();
323	    };
324	  }
325	
326	  function renderGroupByControl() {
327	    const container = document.querySelector<HTMLElement>("[data-graph-group-by]");
328	    if (!container) return;
329	    container.innerHTML = "";
330	    GROUPINGS.forEach((grouping) => {
331	      const button = document.createElement("button");
332	      button.type = "button";
333	      button.textContent = grouping.label;
334	      button.classList.toggle("is-active", grouping.key === activeGrouping.key);
335	      button.addEventListener("click", () => {
336	        activeGrouping = grouping;
337	        container.querySelectorAll("button").forEach((b) => b.classList.remove("is-active"));
338	        button.classList.add("is-active");
339	        rebuildAndRender?.();
340	      });
341	      container.append(button);
342	    });
343	  }
344	
345	  root = d3.hierarchy(buildTree());
346	  root.children?.forEach((child) => collapseAll(child));
347	
348	  renderGroupByControl();
349	  render();
350	  rebuildAndRender = () => {
351	    root = d3.hierarchy(buildTree());
352	    root.children?.forEach((child) => collapseAll(child));
353	    selectedLeafId = null;
354	    render();
355	  };
356	
357	  document.querySelector("[data-graph-expand-all]")?.addEventListener("click", () => {
358	    root.each((n) => expandAll(n));
359	    render();
360	  });
361	  document.querySelector("[data-graph-collapse-all]")?.addEventListener("click", () => {
362	    root.children?.forEach((child) => collapseAll(child));
363	    render();
364	  });
