input.old_string:
  node
    .append("circle")
    .attr("r", (d) => (d.data.entry ? 6 : 7))
    .attr("fill", (d) => {
      const groupKey = d.data.entry ? activeGrouping.get(d.data.entry) : d.data.name;
      if (!d.data.entry && !d.children && !d.data._children) return "var(--color-muted)";
      return `${color(groupKey)}${d.data.entry ? "33" : "55"}`;
    })
    .attr("stroke", (d) => {
      const groupKey = d.data.entry ? activeGrouping.get(d.data.entry) : d.data.name;
      return color(groupKey);
    })
    .attr("stroke-width", (d) => (d.data.entry?.name === selectedLeafId ? 3 : 1.5));

  // Branch nodes with hidden children get a "+" to signal they expand.
  node
    .filter((d) => !d.data.entry && !!d.data._children)
    .append("text")
    .attr("x", 0)
    .attr("y", 3)
    .attr("text-anchor", "middle")
    .attr("font-size", 9)
    .attr("fill", "var(--color-bg, white)")
    .text("+");

  node
    .append("text")
    .attr("x", (d) => (d.children || d.data._children ? -12 : 11))
    .attr("y", 3)
    .attr("text-anchor", (d) => (d.children || d.data._children ? "end" : "start"))
    .attr("fill", "var(--color-ink)")
    .attr("font-weight", (d) => (d.data.entry ? 400 : 650))
    .attr("font-size", (d) => (d.data.entry ? 10 : 11))
    .text((d) => d.data.name);

  node.on("click", (_event, d) => {
    if (!d.data.entry) {
      // Branch node: toggle expand/collapse.
      if (d.data.children) {
        d.data._children = d.data.children;
        d.data.children = undefined;
      } else if (d.data._children) {
        d.data.children = d.data._children;
        d.data._children = undefined;
      }
      selectedLeafId = null;
      crossLinkLayer.selectAll("*").remove();
      draw();
      return;
    }
    // Leaf node: select it, show detail, draw cross-links to visible siblings.
    selectedLeafId = d.data.entry.name;
    showDetails(details, d.data.entry);
    drawCrossLinks(d, nodes);
    draw();
  });

  zoomToNode = (id: string) => {
    // Expand every ancestor branch so the target leaf is visible.
    let found: d3.HierarchyNode<TreeDatum> | null = null;
    root.each((n) => {
      if (n.data.entry?.name === id) found = n;
    });
    if (!found) return;
    let ancestor = (found as d3.HierarchyNode<TreeDatum>).parent;
    while (ancestor) {
      if (ancestor.data._children) {
        ancestor.data.children = ancestor.data._children;
        ancestor.data._children = undefined;
      }
      ancestor = ancestor.parent;
    }
    draw();
    const target = treeLayout(root as d3.HierarchyNode<TreeDatum>)
      .descendants()
      .find((n) => (n as HNode).data.entry?.name === id) as HNode | undefined;
    if (!target) return;
    selectedLeafId = id;
    showDetails(details, target.data.entry!);
    drawCrossLinks(target, treeLayout(root as d3.HierarchyNode<TreeDatum>).descendants() as HNode[]);
    draw();
    svg
      .transition()
      .duration(450)
      .call(
        zoomBehavior.transform,
        d3.zoomIdentity
          .translate(width / 2, height / 2)
          .scale(1.6)
          .translate(-(target.y + margin.left), -(target.x + margin.top))
      );
  };
}

