.graph-canvas p {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  margin: 0;
  color: var(--color-muted);
  font-size: 0.85rem;
}

.graph-canvas svg {
  display: block;
  width: 100%;
  height: 100%;
}

.graph-details {
  padding: 1rem;
  border: 1px solid var(--color-rule);
  border-radius: 0.75rem;
  overflow: auto;
}

