  color: var(--color-accent);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.graph-details h2 {
  margin: 0.4rem 0 0.3rem;
  font-size: 1rem;
  color: var(--color-ink);
}

.graph-details p {
  margin: 0.2rem 0;
  color: var(--color-muted);
  font-size: 0.8rem;
}

.graph-legend {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin: 1rem 0 0;
  padding: 0.75rem 0 0;
  border-top: 1px solid var(--color-rule);
  list-style: none;
}

.graph-legend li {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--color-muted);
  font-size: 0.72rem;
}

.graph-legend i {
  display: inline-block;
  width: 0.6rem;
  height: 0.6rem;
  border: 1.5px solid;
  border-radius: 50%;
}

