content.content:
1	---
2	// Layout inspired by LemonAdorable/astro-theme-iris's knowledge-graph component
3	// (Apache-2.0): https://github.com/LemonAdorable/astro-theme-iris
4	// Reworked here as a collapsible tree (branch = current grouping) with
5	// shared-tag cross-links drawn on top of the selected leaf, rather than a
6	// free-floating force graph — 90 nodes is too many to scan without structure.
7	import type { SkillEntry } from "@data/skills";
8	
9	interface Props {
10	  entries: SkillEntry[];
11	}
12	
13	const { entries } = Astro.props;
14	---
15	
16	<div class="graph-toolbar">
17	  <label class="graph-search">
18	    <span>Find a node</span>
19	    <input type="search" placeholder="Search by name..." data-graph-search autocomplete="off" />
20	    <div data-graph-suggestions hidden></div>
21	  </label>
22	
23	  <fieldset class="graph-group-by">
24	    <legend>Branch by</legend>
25	    <div class="segmented" data-graph-group-by></div>
26	  </fieldset>
27	
28	  <div class="graph-toolbar-actions">
29	    <button type="button" data-graph-expand-all>Expand all</button>
30	    <button type="button" data-graph-collapse-all>Collapse all</button>
31	  </div>
32	</div>
33	
34	<p class="graph-shape-key">
35	  <span class="shape-dot shape-circle" aria-hidden="true"></span> circle = skill
36	  <span class="shape-dot shape-square" aria-hidden="true"></span> square = tool
37	</p>
38	
39	<div class="skills-graph">
40	  <div class="graph-canvas" data-graph-canvas>
41	    <p data-graph-status>Loading graph...</p>
42	  </div>
43	  <aside class="graph-details" data-graph-details>
44	    <span>Node</span>
45	    <h2>Click a leaf</h2>
46	    <p>Branch nodes expand/collapse. Leaf nodes show detail and highlight shared-tag cross-links.</p>
47	    <ul class="graph-legend" data-graph-legend></ul>
48	  </aside>
49	</div>
50	
51	<script type="application/json" data-graph-entries set:html={JSON.stringify(entries)} />
52	
53	<script>
54	  import * as d3 from "d3";
55	  import type { SkillEntry } from "@data/skills";
56	
57	  interface TreeDatum {
58	    name: string;
59	    entry?: SkillEntry; // present on leaves only
60	    children?: TreeDatum[];
61	  }
62	
63	  // Collapse state lives on the D3 hierarchy node itself (`_children`),
64	  // not on the plain data object — this is the standard d3 collapsible-tree
65	  // convention. Only group nodes (depth 1) ever carry `_children`; leaves
66	  // never have `children` in the source data, so they never collapse.
67	  type CNode = d3.HierarchyNode<TreeDatum> & { _children?: CNode[] };
68	  type HNode = d3.HierarchyPointNode<TreeDatum> & { _children?: HNode[] };
69	
70	  // Heuristic: which plugin/marketplace a skill's name maps to. Only the
71	  // two Scalekit-flavored plugins (authstack, skillkit) and the two with a
72	  // real SKILL.md on disk (pm-skills, caveman) are known — see
73	  // docs/research/local-tools-skills-inventory.md. Everything else falls
74	  // back to "ungrouped" rather than guessing.
75	  function deriveSource(e: SkillEntry): string {
76	    const n = e.name.toLowerCase();
77	    if (/saaskit|agentkit|scim|sso|access-control/.test(n)) return "authstack (saaskit/agentkit)";
78	    if (/^docs-|^devrel-|journey-sidebar|review-scalekit-code|^ask-devex|mcp-server|sdk-craft|sdk-development|deploy-self-hosted|run-dryrun/.test(n))
79	      return "skillkit (scalekit/docs)";
80	    if (n === "skill-authoring-workflow" || n === "product-sense-interview-answer") return "pm-skills";
81	    if (n === "caveman" || n === "caveman-compress") return "caveman";
82	    return "ungrouped";
83	  }
84	
85	  // Add an entry here to offer another way to branch the tree. `order`
86	  // (optional) pins known group values first; anything not listed falls in
87	  // afterward in first-seen order.
88	  const GROUPINGS: { key: string; label: string; get: (e: SkillEntry) => string; order?: string[] }[] = [
89	    { key: "domain", label: "Domain", get: (e) => e.domain },
90	    { key: "agent", label: "Agent", get: (e) => e.agent },
91	    { key: "type", label: "Type", get: (e) => e.type },
92	    {
93	      key: "source",
94	      label: "Source",
95	      get: deriveSource,
96	      order: ["authstack (saaskit/agentkit)", "skillkit (scalekit/docs)", "pm-skills", "caveman", "ungrouped"],
97	    },
98	  ];
99	
100	  function orderedGroupValues(values: string[], order?: string[]): string[] {
101	    if (!order) return values;
102	    const known = order.filter((v) => values.includes(v));
103	    const rest = values.filter((v) => !order.includes(v));
104	    return [...known, ...rest];
105	  }
106	
107	  const PALETTE = [
108	    "#8b5cf6",
109	    "#0ea5e9",
110	    "#10b981",
111	    "#f59e0b",
112	    "#ef4444",
113	    "#ec4899",
114	    "#14b8a6",
115	    "#6366f1",
116	  ];
117	
118	  const scriptEl = document.querySelector<HTMLScriptElement>("[data-graph-entries]");
119	  const entries: SkillEntry[] = scriptEl ? JSON.parse(scriptEl.textContent || "[]") : [];
120	
121	  let activeGrouping = GROUPINGS[0];
122	  let root: CNode;
123	  let selectedLeafId: string | null = null;
124	  let color: d3.ScaleOrdinal<string, string>;
125	
126	  function buildTree(): TreeDatum {
127	    const groups = new Map<string, TreeDatum[]>();
128	    entries.forEach((entry) => {
129	      const key = activeGrouping.get(entry);
130	      if (!groups.has(key)) groups.set(key, []);
131	      groups.get(key)!.push({ name: entry.name, entry });
132	    });
133	    const orderedKeys = orderedGroupValues(Array.from(groups.keys()), activeGrouping.order);
134	    return {
135	      name: "All",
136	      children: orderedKeys.map((name) => ({ name, children: groups.get(name)! })),
137	    };
138	  }
139	
140	  // Fresh hierarchy, every group node starts collapsed so the initial view
141	  // is scannable at ~90 leaves.
142	  function buildRoot(): CNode {
143	    const r = d3.hierarchy(buildTree()) as CNode;
144	    r.children?.forEach((group: CNode) => {
145	      if (group.children) {
146	        group._children = group.children as CNode[];
147	        group.children = undefined;
148	      }
149	    });
150	    return r;
151	  }
152	
153	  // Every other entry that shares a tag with this one, and which tag causes
154	  // the connection — computed against the full data set, not just whatever
155	  // is currently expanded in the tree, so the panel stays accurate even
156	  // when the related node's branch is collapsed.
157	  function getRelations(entry: SkillEntry): { name: string; tag: string }[] {
158	    return entries
159	      .filter((e) => e.name !== entry.name)
160	      .map((e) => ({ name: e.name, tag: e.tags.find((t) => entry.tags.includes(t)) }))
161	      .filter((r): r is { name: string; tag: string } => !!r.tag);
162	  }
163	
164	  function showDetails(details: HTMLElement, entry: SkillEntry) {
165	    const legend = details.querySelector("[data-graph-legend]")?.outerHTML ?? "";
166	    const relations = getRelations(entry);
167	    const relationsHtml = relations.length
168	      ? `<div class="graph-relations">
169	          <span>Connects to (${relations.length})</span>
170	          <ul>
171	            ${relations
172	              .map((r) => `<li><button type="button" data-jump-to="${r.name}">${r.name}</button> <em>#${r.tag}</em></li>`)
173	              .join("")}
174	          </ul>
175	        </div>`
176	      : `<div class="graph-relations"><span>Connects to</span><p>No shared tags with other visible entries.</p></div>`;
177	    details.innerHTML = `
178	      <span>Node</span>
179	      <h2>${entry.name}</h2>
180	      <p>${entry.type} · ${entry.domain} · ${entry.agent}</p>
181	      <p>${entry.tags.map((t) => `#${t}`).join(" ")}</p>
182	      ${relationsHtml}
183	      ${legend}
184	    `;
185	    details.querySelectorAll<HTMLButtonElement>("[data-jump-to]").forEach((button) => {
186	      button.addEventListener("click", () => zoomToNode?.(button.dataset.jumpTo!));
187	    });
188	  }
189	
190	  let zoomToNode: ((id: string) => void) | null = null;
191	  let rebuildAndRender: (() => void) | null = null;
192	
193	  function render() {
194	    const canvas = document.querySelector<HTMLElement>("[data-graph-canvas]");
195	    const details = document.querySelector<HTMLElement>("[data-graph-details]");
196	    const legendEl = document.querySelector<HTMLElement>("[data-graph-legend]");
197	    if (!canvas || !details) return;
198	
199	    const width = canvas.clientWidth || 900;
200	    const height = canvas.clientHeight || 640;
201	    canvas.innerHTML = "";
202	
203	    const groupValues = orderedGroupValues(
204	      Array.from(new Set(entries.map((e) => activeGrouping.get(e)))),
205	      activeGrouping.order
206	    );
207	    color = d3.scaleOrdinal<string, string>().domain(groupValues).range(PALETTE);
208	
209	    if (legendEl) {
210	      legendEl.innerHTML = groupValues
211	        .map((v) => `<li><i style="background:${color(v)}33;border-color:${color(v)}"></i>${v}</li>`)
212	        .join("");
213	    }
214	
215	    const margin = { top: 20, right: 180, bottom: 20, left: 90 };
216	    const treeLayout = d3.tree<TreeDatum>().size([height - margin.top - margin.bottom, width - margin.left - margin.right]);
217	
218	    const svg = d3
219	      .select(canvas)
220	      .append("svg")
221	      .attr("viewBox", `0 0 ${width} ${height}`)
222	      .attr("role", "img")
223	      .attr("aria-label", "Skills and tools tree");
224	
225	    const viewport = svg.append("g").attr("transform", `translate(${margin.left},${margin.top})`);
226	    const zoomBehavior = d3
227	      .zoom<SVGSVGElement, unknown>()
228	      .scaleExtent([0.3, 3])
229	      .on("zoom", (event) => viewport.attr("transform", event.transform));
230	    svg.call(zoomBehavior);
231	
232	    const linkLayer = viewport.append("g").attr("class", "tree-links");
233	    const crossLinkLayer = viewport.append("g").attr("class", "cross-links");
234	    const nodeLayer = viewport.append("g").attr("class", "tree-nodes");
235	
236	    function draw() {
237	      const treeRoot = treeLayout(root as unknown as d3.HierarchyNode<TreeDatum>) as HNode;
238	      const nodes = treeRoot.descendants() as HNode[];
239	      const links = treeRoot.links();
240	
241	      linkLayer
242	        .selectAll("path")
243	        .data(links, (d: any) => d.target.data.name + (d.target.data.entry?.name ?? ""))
244	        .join("path")
245	        .attr("fill", "none")
246	        .attr("stroke", "var(--color-rule)")
247	        .attr("stroke-width", 1.2)
248	        .attr(
249	          "d",
250	          d3
251	            .linkHorizontal<any, HNode>()
252	            .x((d) => d.y)
253	            .y((d) => d.x)
254	        );
255	
256	      const node = nodeLayer
257	        .selectAll<SVGGElement, HNode>("g")
258	        .data(nodes, (d: any) => d.data.name + (d.data.entry?.name ?? ""))
259	        .join("g")
260	        .attr("transform", (d) => `translate(${d.y},${d.x})`)
261	        .style("cursor", "pointer");
262	
263	      node.selectAll("*").remove();
264	
265	      // Shape encodes type (skill = circle, tool = square) independent of
266	      // whatever dimension is currently coloring the nodes — color alone
267	      // can't carry both the active grouping AND type at once.
268	      const symbolGen = d3.symbol<HNode>().size((d) => (d.data.entry ? 60 : 80));
269	      node
270	        .append("path")
271	        .attr("d", (d) =>
272	          symbolGen.type(!d.data.entry ? d3.symbolCircle : d.data.entry.type === "tool" ? d3.symbolSquare : d3.symbolCircle)(d)
273	        )
274	        .attr("fill", (d) => {
275	          const groupKey = d.data.entry ? activeGrouping.get(d.data.entry) : d.data.name;
276	          return `${color(groupKey)}${d.data.entry ? "33" : "55"}`;
277	        })
278	        .attr("stroke", (d) => {
279	          const groupKey = d.data.entry ? activeGrouping.get(d.data.entry) : d.data.name;
280	          return color(groupKey);
281	        })
282	        .attr("stroke-width", (d) => (d.data.entry?.name === selectedLeafId ? 3 : 1.5));
283	
284	      // Branch nodes with hidden children get a "+" to signal they expand.
285	      node
286	        .filter((d) => !d.data.entry && !!d._children)
287	        .append("text")
288	        .attr("x", 0)
289	        .attr("y", 3)
290	        .attr("text-anchor", "middle")
291	        .attr("font-size", 9)
292	        .attr("fill", "var(--color-paper)")
293	        .text("+");
294	
295	      node
296	        .append("text")
297	        .attr("x", (d) => (d.children || d._children ? -12 : 11))
298	        .attr("y", 3)
299	        .attr("text-anchor", (d) => (d.children || d._children ? "end" : "start"))
300	        .attr("fill", "var(--color-ink)")
301	        .attr("font-weight", (d) => (d.data.entry ? 400 : 650))
302	        .attr("font-size", (d) => (d.data.entry ? 10 : 11))
303	        .text((d) => d.data.name);
304	
305	      node.on("click", (_event, d) => {
306	        if (!d.data.entry) {
307	          // Branch node: toggle expand/collapse (state lives on the node, not the data).
308	          const target = d as unknown as CNode;
309	          if (target.children) {
310	            target._children = target.children as CNode[];
311	            target.children = undefined;
312	          } else if (target._children) {
313	            target.children = target._children;
314	            target._children = undefined;
315	          }
316	          selectedLeafId = null;
317	          crossLinkLayer.selectAll("*").remove();
318	          draw();
319	          return;
320	        }
321	        // Leaf node: select it, show detail, draw cross-links, keep it in view.
322	        selectedLeafId = d.data.entry.name;
323	        showDetails(details, d.data.entry);
324	        drawCrossLinks(d, nodes);
325	        draw();
326	        panToNode(d);
327	      });
328	
329	      // Keeps a selected leaf centered in the viewport — without this, a
330	      // plain click on a leaf far from the current pan position leaves its
331	      // cross-links appearing to start from off-screen.
332	      function panToNode(target: HNode) {
333	        svg
334	          .transition()
335	          .duration(450)
336	          .call(
337	            zoomBehavior.transform,
338	            d3.zoomIdentity
339	              .translate(width / 2, height / 2)
340	              .scale(1.6)
341	              .translate(-(target.y + margin.left), -(target.x + margin.top))
342	          );
343	      }
344	
345	      zoomToNode = (id: string) => {
346	        const entry = entries.find((e) => e.name === id);
347	        if (!entry) return;
348	        // Group nodes (root.children) are never themselves collapsed, only
349	        // their leaves are — so this lookup always finds the right group.
350	        const groupName = activeGrouping.get(entry);
351	        const groupNode = root.children?.find((g) => g.data.name === groupName) as CNode | undefined;
352	        if (groupNode?._children) {
353	          groupNode.children = groupNode._children;
354	          groupNode._children = undefined;
355	        }
356	        draw();
357	        const freshNodes = (treeLayout(root as unknown as d3.HierarchyNode<TreeDatum>) as HNode).descendants() as HNode[];
358	        const target = freshNodes.find((n) => n.data.entry?.name === id);
359	        if (!target) return;
360	        selectedLeafId = id;
361	        showDetails(details, target.data.entry!);
362	        drawCrossLinks(target, freshNodes);
363	        draw();
364	        panToNode(target);
365	      };
366	    }
367	
368	    function drawCrossLinks(source: HNode, allNodes: HNode[]) {
369	      crossLinkLayer.selectAll("*").remove();
370	      if (!source.data.entry) return;
371	      const sourceTags = new Set(source.data.entry.tags);
372	      const targets = allNodes.filter(
373	        (n) => n.data.entry && n.data.entry.name !== source.data.entry!.name && n.data.entry.tags.some((t) => sourceTags.has(t))
374	      );
375	      crossLinkLayer
376	        .selectAll("path")
377	        .data(targets)
378	        .join("path")
379	        .attr("fill", "none")
380	        .attr("stroke", "var(--color-focus)")
381	        .attr("stroke-width", 1.3)
382	        .attr("stroke-dasharray", "3 3")
383	        .attr("opacity", 0.75)
384	        .attr("d", (d) => {
385	          const dx = d.y - source.y;
386	          const dy = d.x - source.x;
387	          const dr = Math.sqrt(dx * dx + dy * dy) * 1.4;
388	          return `M${source.y},${source.x} A${dr},${dr} 0 0,1 ${d.y},${d.x}`;
389	        });
390	    }
391	
392	    draw();
393	  }
394	
395	  function renderGroupByControl() {
396	    const container = document.querySelector<HTMLElement>("[data-graph-group-by]");
397	    if (!container) return;
398	    container.innerHTML = "";
399	    GROUPINGS.forEach((grouping) => {
400	      const button = document.createElement("button");
401	      button.type = "button";
402	      button.textContent = grouping.label;
403	      button.classList.toggle("is-active", grouping.key === activeGrouping.key);
404	      button.addEventListener("click", () => {
405	        activeGrouping = grouping;
406	        container.querySelectorAll("button").forEach((b) => b.classList.remove("is-active"));
407	        button.classList.add("is-active");
408	        rebuildAndRender?.();
409	      });
410	      container.append(button);
411	    });
412	  }
413	
414	  root = buildRoot();
415	  rebuildAndRender = () => {
416	    root = buildRoot();
417	    selectedLeafId = null;
418	    render();
419	  };
420	
421	  renderGroupByControl();
422	  render();
423	
424	  document.querySelector("[data-graph-expand-all]")?.addEventListener("click", () => {
425	    root.children?.forEach((group: CNode) => {
426	      if (group._children) {
427	        group.children = group._children;
428	        group._children = undefined;
429	      }
430	    });
431	    render();
432	  });
433	  document.querySelector("[data-graph-collapse-all]")?.addEventListener("click", () => {
434	    root.children?.forEach((group: CNode) => {
435	      if (group.children) {
436	        group._children = group.children as CNode[];
437	        group.children = undefined;
438	      }
439	    });
440	    selectedLeafId = null;
441	    render();
442	  });
443	
444	  const search = document.querySelector<HTMLInputElement>("[data-graph-search]");
445	  const suggestions = document.querySelector<HTMLElement>("[data-graph-suggestions]");
446	  if (search && suggestions) {
447	    search.addEventListener("input", () => {
448	      const query = search.value.trim().toLowerCase();
449	      suggestions.replaceChildren();
450	      if (!query) {
451	        suggestions.hidden = true;
452	        return;
453	      }
454	      const matches = entries.filter((e) => e.name.toLowerCase().includes(query)).slice(0, 8);
455	      matches.forEach((entry) => {
456	        const button = document.createElement("button");
457	        button.type = "button";
458	        button.dataset.suggestion = "";
459	        button.textContent = entry.name;
460	        button.addEventListener("click", () => {
461	          search.value = entry.name;
462	          suggestions.hidden = true;
463	          zoomToNode?.(entry.name);
464	        });
465	        suggestions.append(button);
466	      });
467	      suggestions.hidden = matches.length === 0;
468	    });
469	
470	    search.addEventListener("keydown", (event) => {
471	      if (event.key !== "Enter") return;
472	      const query = search.value.trim().toLowerCase();
473	      const match = entries.find((e) => e.name.toLowerCase().includes(query));
474	      if (match) {
475	        suggestions.hidden = true;
476	        zoomToNode?.(match.name);
477	      }
478	    });
479	  }
480	</script>
481	
